import re

def normalize_ticket_id(raw):
    return re.sub(r'[\s_]+', '-', raw.strip()).upper()

import re

def parse_duration(text):
    factors = {'h': 3600, 'm': 60, 's': 1}
    return sum(int(n) * factors[u] for n, u in re.findall(r'(\d+)([hms])', text))

def bucket_by_length(words):
    groups = {}
    for w in words:
        groups.setdefault(len(w), []).append(w)
    return [groups[k] for k in sorted(groups)]

def compress_ranges(numbers):
    nums = sorted(set(numbers))
    out = []
    i = 0
    while i < len(nums):
        j = i
        while j + 1 < len(nums) and nums[j + 1] == nums[j] + 1:
            j += 1
        out.append(str(nums[i]) if i == j else f'{nums[i]}-{nums[j]}')
        i = j + 1
    return ','.join(out)

def schedule_conflicts(meetings):
    out = []
    for i in range(len(meetings)):
        for j in range(i + 1, len(meetings)):
            if meetings[i][0] < meetings[j][1] and meetings[j][0] < meetings[i][1]:
                out.append([i, j])
    return out
